WITH filtered AS (SELECT *, CAST(duration_sec AS DOUBLE) AS duration_sec_num FROM web_events WHERE page IS NOT NULL), with_gaps AS (SELECT *, CASE WHEN event_time - LAG(event_time) OVER (PARTITION BY session_id ORDER BY event_time, id) > INTERVAL 60 DAYS THEN 1 ELSE 0 END AS new_group_flag FROM filtered), sessions_web_events AS (SELECT id, session_id, event_type, event_time, duration_sec_num, SUM(new_group_flag) OVER (PARTITION BY session_id ORDER BY event_time, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS island_id FROM with_gaps) SELECT CASE WHEN duration_sec_num >= 85 THEN 'LARGE' ELSE 'SMALL' END AS duration_sec_num_tier, CASE WHEN island_id >= 8 THEN 'LARGE' ELSE 'SMALL' END AS island_id_tier, AVG(island_id) FILTER (WHERE event_type = 'purchase') AS purchase_avg_island_id, SUM(duration_sec_num) FILTER (WHERE event_type = 'search') AS search_total_duration_sec_num, COUNT_IF(event_type = 'search') AS search_events, SIZE(COLLECT_SET(event_type)) AS num_event_types, APPROX_PERCENTILE(duration_sec_num, 0.9) AS duration_sec_num_p90, PERCENT_RANK() OVER (PARTITION BY CASE WHEN duration_sec_num >= 85 THEN 'LARGE' ELSE 'SMALL' END ORDER BY AVG(island_id) FILTER (WHERE event_type = 'purchase') DESC) AS purchase_avg_island_id_percent_rank FROM sessions_web_events GROUP BY CASE WHEN duration_sec_num >= 85 THEN 'LARGE' ELSE 'SMALL' END, CASE WHEN island_id >= 8 THEN 'LARGE' ELSE 'SMALL' END ORDER BY duration_sec_num_p90 DESC NULLS FIRST;
